"""QuantCraft IDE — Basic MA Crossover Strategy"""

import quantcraft.backtest.runtime as rt
from quantcraft.backtest.runtime import account, chart_indicators
from ide.inputs_module import params
from indicators.sma import calculate_sma, has_sufficient_data, get_closes_for_period
from utils.position_sizing import calculate_position_size, can_afford_position
from utils.account_helpers import (
    get_symbol_positions,
    count_symbol_positions,
    has_room_for_more_positions,
    close_all_symbol_positions,
)
from utils.chart_helpers import calculate_and_add_ma_series
from quantcraft.backtest.ohlcv import QcOhlcv, qc_ohlcv

# Strategy configuration from inputs
MA_PERIOD = (
    params.MA_PERIOD if hasattr(params, "MA_PERIOD") else 24
)  # Default to 24 if not set
MAX_POSITIONS = (
    params.MAX_POSITIONS if hasattr(params, "MAX_POSITIONS") else 5
)  # Default to 5 if not set
RISK_PCT = (
    params.RISK_PCT if hasattr(params, "RISK_PCT") else 0.01
)  # Default to 1% if not set

# Strategy state - track per symbol
symbol_states = {}  # symbol -> {"last_ma": value, "last_price": value}


def on_init():
    """Initialize strategy parameters."""
    global symbol_states
    print("initialized")

    print("[Strategy] Initializing MA Crossover Strategy")
    print(f"[Strategy] MA Period: {MA_PERIOD}")
    print(f"[Strategy] Max Positions: {MAX_POSITIONS}")
    print(f"[Strategy] Risk per Trade: {RISK_PCT:.1%}")

    # Reset strategy state
    symbol_states = {}


def on_tick(bar_index, tick_in_bar, price, bar, fundamentals=None, symbol=None):
    """Handle tick events - not used in this bar-based strategy."""
    print("tick received", symbol)
    closes = [bar.close[i] for i in range(min(6, len(bar.close)))]
    print(" | ".join(f"[{i}] {c:.4f} {bar.t[i]}" for i, c in enumerate(closes)))

    pass


def on_bar(bar_index, bar, fundamentals=None, symbol=None):
    print("bar received", symbol)
    closes = [bar.close[i] for i in range(min(6, len(bar.close)))]
    print(" | ".join(f"[{i}] {c:.4f} {bar.t[i]}" for i, c in enumerate(closes)))

    """Main strategy logic - runs once per bar."""
    if account is None:
        return

    # Get current price and symbol
    current_price = float(bar["close"])
    current_symbol = (symbol or "UNKNOWN").upper()

    # Initialize symbol state if not exists
    if current_symbol not in symbol_states:
        symbol_states[current_symbol] = {"last_ma": None, "last_price": None}

    symbol_state = symbol_states[current_symbol]

    # Check if we have sufficient data for MA calculation
    if not has_sufficient_data(bar, MA_PERIOD):
        print(
            f"[Strategy] {current_symbol} Bar {bar_index}: Warming up... need {MA_PERIOD} bars, have {bar.bars_back}"
        )
        return

    # Get closes and calculate MA
    closes = get_closes_for_period(bar, MA_PERIOD)
    if not closes:
        print(
            f"[Strategy] {current_symbol} Bar {bar_index}: Insufficient data for MA calculation"
        )
        return

    current_ma = calculate_sma(closes, MA_PERIOD)
    if current_ma is None:
        return

    # Get current account snapshot
    # For multi-symbol, we need to provide prices for all symbols we might have positions in
    all_symbols_prices = _get_all_symbol_prices(current_symbol, current_price)
    snap = account.tick(all_symbols_prices)
    open_positions = snap["open_positions"]

    # Get positions for this symbol
    symbol_positions = get_symbol_positions(open_positions, current_symbol, "long")
    position_count = count_symbol_positions(open_positions, current_symbol, "long")

    # Get last values for this symbol
    last_price = symbol_state["last_price"]
    last_ma = symbol_state["last_ma"]

    # Entry logic: price crosses above MA and we have room for more positions
    if _should_enter_long(
        last_price, last_ma, current_price, current_ma, position_count
    ):
        _execute_entry(current_symbol, current_price, snap, bar_index, current_ma)

    # Exit logic: price crosses below MA
    elif _should_exit_long(
        last_price, last_ma, current_price, current_ma, position_count
    ):
        _execute_exit(
            symbol_positions, current_symbol, current_price, bar_index, current_ma
        )

    # Store values for next bar comparison FOR THIS SYMBOL
    symbol_states[current_symbol]["last_ma"] = current_ma
    symbol_states[current_symbol]["last_price"] = current_price


def _get_all_symbol_prices(current_symbol, current_price):
    """Get prices for all symbols we're tracking or have positions in."""
    prices = {current_symbol: current_price}

    # Add any other symbols we have state for (in case we have positions)
    # This ensures account.tick() can properly value all positions
    for sym in symbol_states.keys():
        if sym != current_symbol and sym not in prices:
            # We don't have current price for this symbol in this bar
            # account.tick() will use entry price as fallback
            pass

    return prices


def _should_enter_long(last_price, last_ma, current_price, current_ma, position_count):
    """Determine if we should enter a long position."""
    return (
        last_ma is not None
        and last_price is not None
        and position_count < MAX_POSITIONS
        and last_price <= last_ma
        and current_price > current_ma
    )


def _should_exit_long(last_price, last_ma, current_price, current_ma, position_count):
    """Determine if we should exit long positions."""
    return (
        last_ma is not None
        and last_price is not None
        and position_count > 0
        and last_price >= last_ma
        and current_price < current_ma
    )


def _execute_entry(symbol, price, snap, bar_index, ma_value):
    """Execute entry trade."""
    balance = snap["balance"]
    qty = calculate_position_size(balance, price, RISK_PCT)

    if qty > 0 and can_afford_position(balance, qty, price):
        result = account.open_trade(symbol, "long", qty, price)
        print(
            f"[Strategy] {symbol} Bar {bar_index}: BUY {qty} shares at ${price:.2f} (MA: ${ma_value:.2f})"
        )
        print(
            f"[Strategy] {symbol} Open positions: {len([p for p in result['open_positions'] if p['symbol'] == symbol])}"
        )
    else:
        print(
            f"[Strategy] {symbol} Bar {bar_index}: Entry signal but insufficient funds or invalid qty"
        )


def _execute_exit(positions, symbol, price, bar_index, ma_value):
    """Execute exit trades for all symbol positions."""
    close_results = close_all_symbol_positions(account, positions, symbol, price)

    for result in close_results:
        if result["success"]:
            position = result["position"]
            account_result = result["result"]
            print(
                f"[Strategy] {symbol} Bar {bar_index}: SELL {position['qty']} shares at ${price:.2f} (MA: ${ma_value:.2f})"
            )
            print(
                f"[Strategy] {symbol} Realized P/L: ${account_result['realized_pnl']:.2f}"
            )
        else:
            print(
                f"[Strategy] {symbol} Bar {bar_index}: Failed to close position - {result['error']}"
            )


def on_timer(bar_index, tick_in_bar, price, bar, fundamentals=None, symbol=None):
    """Timer events - not used in this strategy."""
    pass


def on_finish(bars, symbol=None, bars_by_symbol=None):
    """Strategy completion - calculate final metrics and add indicators to chart."""
    if account is None:
        return

    print("[Strategy] Backtest completed")

    # Add MA indicator to chart using complete bars data
    # For multi-symbol, use the primary symbol's bars
    if chart_indicators is not None and bars:
        print(
            f"[Strategy] Adding SMA({MA_PERIOD}) to chart with {len(bars)} bars (symbol: {symbol})"
        )
        calculate_and_add_ma_series(chart_indicators, bars, MA_PERIOD, symbol=symbol)

    # For multi-symbol backtests, bars_by_symbol contains data for each symbol
    if chart_indicators is not None and bars_by_symbol:
        for sym, sym_bars in bars_by_symbol.items():
            if sym != symbol and sym_bars:  # Add indicators for non-primary symbols
                print(
                    f"[Strategy] Adding SMA({MA_PERIOD}) for {sym} with {len(sym_bars)} bars"
                )
                calculate_and_add_ma_series(
                    chart_indicators, sym_bars, MA_PERIOD, symbol=sym
                )

    # Get final prices for metrics calculation
    final_prices = {}

    # Single symbol case
    if bars and symbol:
        final_prices[symbol.upper()] = float(bars[-1]["close"])

    # Multi-symbol case
    if bars_by_symbol:
        for sym, sym_bars in bars_by_symbol.items():
            if sym_bars:
                final_prices[sym.upper()] = float(sym_bars[-1]["close"])

    # Calculate and display final metrics
    metrics = account.refresh_metrics(final_prices)

    print(f"[Strategy] Final Results:")
    print(f"  Total Return: {metrics['total_return']:.2%}")
    print(f"  Total P/L: ${metrics['total_pnl']:.2f}")
    print(f"  Max Drawdown: {metrics['max_drawdown']:.2%}")
    print(f"  Sharpe Ratio: {metrics.get('sharpe_ratio', 'N/A')}")
    print(f"  Total Trades: {len(account.closed_trades)}")

    # Show per-symbol trade statistics
    if account.closed_trades:
        symbol_trades = {}
        for trade in account.closed_trades:
            sym = trade.get("symbol", "UNKNOWN")
            if sym not in symbol_trades:
                symbol_trades[sym] = []
            symbol_trades[sym].append(trade)

        for sym, trades in symbol_trades.items():
            profitable = [t for t in trades if t["realized_pnl"] > 0]
            win_rate = len(profitable) / len(trades) if trades else 0
            total_pnl = sum(t["realized_pnl"] for t in trades)
            print(
                f"  {sym}: {len(trades)} trades, {win_rate:.2%} win rate, ${total_pnl:.2f} P/L"
            )

    print(f"  Final Balance: ${account.cash:.2f}")
    print(f"  Symbols Tracked: {list(symbol_states.keys())}")
